bulkCalls.queryDocument:
query DarpanShopifyOrdersByDateWindow {
  orders(query: "created_at:>='2026-08-01T00:00:00Z' created_at:<'2026-08-02T00:00:00Z'", sortKey: CREATED_AT) {
    edges {
      node {
        cancelledAt
        createdAt
        currencyCode
        currentTotalPriceSet {
          shopMoney {
            amount
            currencyCode
          }
        }
        currentTotalTaxSet {
          shopMoney {
            amount
            currencyCode
          }
        }
        displayFinancialStatus
        displayFulfillmentStatus
        email
        id
        legacyResourceId
        name
        processedAt
        requiresShipping
        sourceName
        subtotalPriceSet {
          shopMoney {
            amount
            currencyCode
          }
        }
        totalPrice
        totalPriceSet {
          shopMoney {
            amount
            currencyCode
          }
        }
        transactions {
          gateway
          kind
          status
        }
        updatedAt
      }
    }
  }
}
